fn real_main() -> i32 {
    let argv: Vec<String> = env::args().collect();
    let raw_args: Vec<String> = argv[1..].to_vec();

    // check --no-config in raw CLI (exact match)
    let mut has_no_config_cli = false;
    for a in &raw_args {
        if a == "--no-config" {
            has_no_config_cli = true;
            break;
        }
        // also handle --no-config with = ? That would be error, but still need to detect? Original would error, but config reading? We'll treat exact only.
    }

    let mut config_args: Vec<String> = Vec::new();
    let mut config_error: Option<String> = None;
    if !has_no_config_cli {
        if let Ok(path) = env::var("RIPGREP_CONFIG_PATH") {
            if !path.is_empty() {
                match fs::File::open(&path) {
                    Ok(mut f) => {
                        let mut content = String::new();
                        match f.read_to_string(&mut content) {
                            Ok(_) => {
                                for line in content.lines() {
                                    let trimmed = line.trim();
                                    if trimmed.is_empty() { continue; }
                                    if trimmed.starts_with('#') { continue; }
                                    config_args.push(trimmed.to_string());
                                }
                            }
                            Err(e) => {
                                config_error = Some(format!("rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {} (os error {})", e.to_string().split(" (os error").next().unwrap_or(&e.to_string()), e.raw_os_error().unwrap_or(0)));
                                // Actually need exact format: "Is a directory (os error 21)" – e.to_string() already gives that? Let's use e.to_string()
                                config_error = Some(format!("rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {}", e));
                            }
                        }
                    }
                    Err(e) => {
                        config_error = Some(format!("rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {}: {}", path, e));
                    }
                }
            }
        }
    }

    // combine: config_args + raw_args
    let mut all_args = config_args.clone();
    all_args.extend(raw_args.clone());

    let mut cfg = Config::new();
    // need to track positions for last-wins: use index in all_args
    match parse_args(&all_args, &mut cfg) {
        Ok(_) => {},
        Err((msg, code)) => {
            eprint!("{}", msg);
            // config error already? No, parse error takes precedence? If config had error and parse error, which to print? Probably parse error only? But config error should also be printed? Original with bad config file + bad CLI? Let's just print parse error.
            return code;
        }
    }

    // print config error to stderr if any (but continue)
    if let Some(err) = config_error {
        eprint!("{}\n", err);
    }

    // handle specials with tier logic
    // tier1: help_short, help_long, version_short, version_long, pcre2_version
    // tier2: generate, type_list, files
    // if any tier1 present, choose latest tier1; else if any tier2, choose latest tier2
    let mut tier1: Vec<(usize, String)> = Vec::new();
    if let Some(p) = cfg.help_short_pos { tier1.push((p, "help_short".to_string())); }
    if let Some(p) = cfg.help_long_pos { tier1.push((p, "help_long".to_string())); }
    if let Some(p) = cfg.version_short_pos { tier1.push((p, "version_short".to_string())); }
    if let Some(p) = cfg.version_long_pos { tier1.push((p, "version_long".to_string())); }
    if let Some(p) = cfg.pcre2_version_pos { tier1.push((p, "pcre2".to_string())); }
    let mut tier2: Vec<(usize, String)> = Vec::new();
    if let Some((_, p)) = &cfg.generate { tier2.push((*p, "generate".to_string())); }
    if let Some(p) = cfg.type_list_pos { tier2.push((p, "typelist".to_string())); }
    if let Some(p) = cfg.files_pos { tier2.push((p, "files".to_string())); }

    if !tier1.is_empty() {
        tier1.sort_by_key(|x| x.0);
        let last = tier1.last().unwrap().1.clone();
        match last.as_str() {
            "help_short" => {
                print!("{}", SHORT_HELP);
                return 0;
            }
            "help_long" => {
                print!("{}", LONG_HELP);
                return 0;
            }
            "version_short" => {
                print!("{}", VERSION_SHORT);
                return 0;
            }
            "version_long" => {
                print!("{}", VERSION_LONG);
                return 0;
            }
            "pcre2" => {
                // PCRE2 not available
                print!("PCRE2 is not available in this build of ripgrep.\n");
                return 1;
            }
            _ => {}
        }
    } else if !tier2.is_empty() {
        tier2.sort_by_key(|x| x.0);
        let last = tier2.last().unwrap().1.clone();
        match last.as_str() {
            "generate" => {
                let (val, _) = cfg.generate.clone().unwrap();
                match val.as_str() {
                    "man" => { print!("{}", MAN_TXT); return 0; }
                    "complete-bash" => { print!("{}", BASH_TXT); return 0; }
                    "complete-zsh" => { print!("{}", ZSH_TXT); return 0; }
                    "complete-fish" => { print!("{}", FISH_TXT); return 0; }
                    "complete-powershell" => { print!("{}", PS_TXT); return 0; }
                    _ => unreachable!(),
                }
            }
            "typelist" => {
                match handle_type_list(&cfg) {
                    Ok(s) => { print!("{}", s); return 0; }
                    Err((msg, code)) => { eprint!("{}", msg); return code; }
                }
            }
            "files" => {
                return handle_files(&cfg);
            }
            _ => {}
        }
    }

    // search mode: need patterns
    // collect patterns from -e, -f, positionals
    return handle_search(&cfg);
}
