fn parse_u64_flag(flag_str: &str, val: &str) -> Result<u64, String> {
    // must be non-empty digits only? Original error for -1, foo, etc. is "value is not a valid number: invalid digit found in string"
    // For empty? Probably same. For overflow? Need to check.
    if val.is_empty() {
        return Err(format!("rg: error parsing flag {}: value is not a valid number: invalid digit found in string\n", flag_str));
    }
