            // Original message is "value is not a valid number: <e>"
            Err(format!("rg: error parsing flag {}: value is not a valid number: {}\n", flag_str, e))
        }
    }
}

fn parse_size_flag(flag_str: &str, val: &str) -> Result<u64, String> {
    if val.is_empty() {
        return Err(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", flag_str, val));
    }
    let (num_part, mult) = if val.ends_with('K') || val.ends_with('k') {
        (&val[..val.len()-1], 1024u64)
    } else if val.ends_with('M') || val.ends_with('m') {
        (&val[..val.len()-1], 1024*1024)
    } else if val.ends_with('G') || val.ends_with('g') {
        (&val[..val.len()-1], 1024*1024*1024)
    } else {
        (val, 1)
    };
    if num_part.is_empty() {
        return Err(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", flag_str, val));
    }
    // num_part must be digits only
    if !num_part.chars().all(|c| c.is_ascii_digit()) {
        return Err(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", flag_str, val));
    }
    match num_part.parse::<u64>() {
        Ok(n) => {
            match n.checked_mul(mult) {
                Some(v) => Ok(v),
                None => Err(format!("rg: error parsing flag {}: invalid size: size too large\n", flag_str)),
            }
        }
        Err(_) => Err(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", flag_str, val)),
    }
}

fn unescape_separator(s: &str) -> String {
    // Handle escape sequences like \x7F, \t, \n, etc.? Original says "Escape sequences like \x7F or \t may be used."
    // Need to implement: \t, \n, \r, \\, \xHH, \0? Let's probe original for separators with escapes.
    // For now, implement \t, \n, \r, \\, \xHH, \0?
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('t') => out.push('\t'),
                Some('n') => out.push('\n'),
                Some('r') => out.push('\r'),
                Some('\\') => out.push('\\'),
                Some('0') => out.push('\0'),
                Some('x') => {
                    let h1 = chars.next();
                    let h2 = chars.next();
                    if let (Some(a), Some(b)) = (h1, h2) {
                        if let (Some(v1), Some(v2)) = (a.to_digit(16), b.to_digit(16)) {
                            let v = (v1*16+v2) as u8;
                            out.push(v as char);
                        } else {
                            out.push('\\');
                            out.push('x');
                            out.push(a);
                            out.push(b);
                        }
                    } else {
                        out.push('\\');
                        out.push('x');
                        if let Some(a) = h1 { out.push(a); }
                        if let Some(b) = h2 { out.push(b); }
                    }
                }
                Some(other) => {
                    out.push('\\');
                    out.push(other);
                }
                None => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn parse_args(all_args: &[String], cfg: &mut Config) -> Result<(), (String, i32)> {
    let mut i = 0usize;
    let mut pos_index = 0usize; // for tier positions: use i as pos
    let mut seen_dashdash = false;
    while i < all_args.len() {
        let arg = &all_args[i];
        let cur_pos = i;
        if seen_dashdash {
            cfg.positionals.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            seen_dashdash = true;
            i += 1;
            continue;
        }
        if arg == "-" {
            cfg.positionals.push(arg.clone());
            i += 1;
            continue;
        }
        if arg.starts_with("--") {
            // long flag
            let without = &arg[2..];
            if without.is_empty() {
                // "--" already handled, "---"? Treat as positional? Actually "---" starts with --, without = "-", is that flag "-"? Probably unrecognized.
                // Let's treat as unrecognized flag "---"?
                return Err((format!("rg: unrecognized flag {}\n", arg), 2));
            }
            let (name, eq_val) = if let Some(eq) = without.find('=') {
                (&without[..eq], Some(&without[eq+1..]))
            } else {
                (without, None)
            };
            if is_value_long_flag(name) {
                let flag_str = format!("--{}", name);
                let val: String;
                if let Some(v) = eq_val {
                    val = v.to_string();
                } else {
                    // need next arg
                    if i+1 >= all_args.len() {
                        return Err((format!("rg: missing value for flag {}: missing argument for option '{}'\n", flag_str, flag_str), 2));
                    }
                    i += 1;
                    val = all_args[i].clone();
                }
                // handle value flag
                handle_long_value(cfg, name, &val, &flag_str, cur_pos)?;
                i += 1;
                continue;
            } else if is_bool_long_flag(name) {
                if eq_val.is_some() {
                    let flag_str = format!("--{}", name);
                    let v = eq_val.unwrap();
                    return Err((format!("rg: invalid CLI arguments: unexpected argument for option '{}': \"{}\"\n", flag_str, v), 2));
                }
                handle_long_bool(cfg, name, cur_pos)?;
                i += 1;
                continue;
            } else {
                // unrecognized, strip =value part for message? Already have name without =.
                let flag_show = format!("--{}", name);
                // TODO: suggestions? For now no suggestions.
                return Err((format!("rg: unrecognized flag {}\n", flag_show), 2));
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // short flags, possibly combined
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            let mut consumed_next = false;
            while j < chars.len() {
                let c = chars[j];
                if short_takes_value(c) {
                    let flag_str = format!("-{}", c);
                    // value is rest of arg after c, or next arg
                    let rest: String = chars[j+1..].iter().collect();
                    let val: String;
                    if !rest.is_empty() {
                        // strip leading '=' if present
                        if rest.starts_with('=') {
                            val = rest[1..].to_string();
                        } else {
                            val = rest;
                        }
                    } else {
                        if i+1 >= all_args.len() {
                            return Err((format!("rg: missing value for flag {}: missing argument for option '{}'\n", flag_str, flag_str), 2));
                        }
                        i += 1;
                        val = all_args[i].clone();
                        consumed_next = true;
                    }
                    handle_short_value(cfg, c, &val, &flag_str, cur_pos)?;
                    // value flag consumes rest, break inner loop
                    break;
                } else if is_bool_short(c) {
                    // check for =value? For bool short, if rest starts with '=', it's unexpected argument? e.g., -i=true
                    // Original: "-i=true" gave unexpected argument for '-i': "true"
                    // How to detect? If chars after c start with '=', then rest[1..] is value, error.
                    // But what about "-iv"? That's -i -v, not -i with value "v". For bool, each char is separate, no attached value except with '='?
                    // For "-in", it's -i -n. For "-i=true", rest is "=true", so error.
                    // For "-u"? It's bool but countable, and "-uuu" means three -u, not -u with value "uu".
                    // So for bool, if rest starts with '=', error.
                    let rest: String = chars[j+1..].iter().collect();
                    if rest.starts_with('=') {
                        let flag_str = format!("-{}", c);
                        let v = &rest[1..];
                        return Err((format!("rg: invalid CLI arguments: unexpected argument for option '{}': \"{}\"\n", flag_str, v), 2));
                    }
                    handle_short_bool(cfg, c, cur_pos)?;
                    j += 1;
                    continue;
                } else {
                    return Err((format!("rg: unrecognized flag -{}\n", c), 2));
                }
            }
            i += 1;
            continue;
        } else {
            // positional
            cfg.positionals.push(arg.clone());
            i += 1;
            continue;
        }
    }
    Ok(())
}

fn handle_long_value(cfg: &mut Config, name: &str, val: &str, flag_str: &str, pos: usize) -> Result<(), (String, i32)> {
    match name {
        "regexp" => { cfg.patterns.push(val.to_string()); }
        "file" => { cfg.pattern_files.push(val.to_string()); }
        "pre" => { cfg.pre = Some(val.to_string()); }
        "pre-glob" => {
            // validate glob?
            if let Err(e) = validate_glob(val) {
                return Err((format!("rg: error parsing glob '{}': {}\n", val, e), 2));
            }
            cfg.pre_globs.push(val.to_string());
        }
        "dfa-size-limit" => {
            match parse_size_flag(flag_str, val) {
