            }
            cfg.engine = val.to_string();
            if val == "pcre2" {
                cfg.pcre2 = true;
            } else if val == "default" {
                cfg.pcre2 = false;
            } else {
                // auto: keep pcre2 false? Actually auto means use pcre2 if needed, but since pcre2 not available, treat as default for now.
                cfg.pcre2 = false;
