                Ok(n) => { cfg.before_context = Some(n); cfg.before_set = true; cfg.before_set_pos = Some(pos); }
                Err(msg) => return Err((msg, 2)),
            }
        }
        "color" => {
            if val != "never" && val != "auto" && val != "always" && val != "ansi" {
                return Err((format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", flag_str, val), 2));
            }
            cfg.color = val.to_string();
        }
        "colors" => {
            if let Err(msg) = validate_colors(val) {
                return Err((format!("rg: error parsing flag {}: {}\n", flag_str, msg), 2));
            }
            cfg.colors.push(val.to_string());
        }
        "context" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => { cfg.context_opt = Some(n); cfg.context_set = true; cfg.context_set_pos = Some(pos); }
                Err(msg) => return Err((msg, 2)),
            }
        }
        "context-separator" => {
            cfg.context_separator = Some(unescape_separator(val));
            cfg.context_separator_is_default = false;
        }
        "field-context-separator" => {
            cfg.field_context_separator = unescape_separator(val);
        }
        "field-match-separator" => {
            cfg.field_match_separator = unescape_separator(val);
        }
        "hostname-bin" => {
            cfg.hostname_bin = Some(val.to_string());
        }
        "hyperlink-format" => {
            if let Err(msg) = validate_hyperlink(val) {
                return Err((format!("rg: error parsing flag {}: {}\n", flag_str, msg), 2));
            }
            cfg.hyperlink_format = Some(val.to_string());
        }
        "max-columns" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.max_columns = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        "path-separator" => {
            if val.is_empty() {
                cfg.path_separator = None;
            } else if val.as_bytes().len() != 1 {
                return Err((format!("rg: error parsing flag {}: A path separator must be exactly one byte, but the given separator is {} bytes: {}\nIn some shells on Windows '/' is automatically expanded. Use '//' instead.\n", flag_str, val.as_bytes().len(), val), 2));
            } else {
                cfg.path_separator = Some(val.as_bytes()[0]);
            }
        }
        "replace" => {
            cfg.replace = Some(val.to_string());
        }
        "sort" => {
            if val != "none" && val != "path" && val != "modified" && val != "accessed" && val != "created" {
                return Err((format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", flag_str, val), 2));
            }
            cfg.sort = Some(val.to_string());
            cfg.sort_pos = Some(pos);
        }
        "sortr" => {
            if val != "none" && val != "path" && val != "modified" && val != "accessed" && val != "created" {
                return Err((format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", flag_str, val), 2));
            }
            cfg.sortr = Some(val.to_string());
            cfg.sortr_pos = Some(pos);
        }
        "generate" => {
            if val != "man" && val != "complete-bash" && val != "complete-zsh" && val != "complete-fish" && val != "complete-powershell" {
                return Err((format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", flag_str, val), 2));
            }
            cfg.generate = Some((val.to_string(), pos));
        }
        _ => unreachable!(),
    }
    Ok(())
}

