fn parse_u64_flag(flag_str: &str, val: &str) -> Result<u64, String> {
    // must be non-empty digits only? Original error for -1, foo, etc. is "value is not a valid number: invalid digit found in string"
    // For empty? Probably same. For overflow? Need to check.
    if val.is_empty() {
        return Err(format!("rg: error parsing flag {}: value is not a valid number: invalid digit found in string\n", flag_str));
    }
    match val.parse::<u64>() {
        Ok(n) => Ok(n),
        Err(e) => {
            // need to distinguish invalid digit vs out of range? Original for huge numbers? Let's test: very large number overflow?
            // For now, use e.to_string() which for ParseIntError gives "invalid digit..." or "number too large..."
            // Original message is "value is not a valid number: <e>"
            Err(format!("rg: error parsing flag {}: value is not a valid number: {}\n", flag_str, e))
        }
    }
}

fn parse_size_flag(flag_str: &str, val: &str) -> Result<u64, String> {
    if val.is_empty() {
        return Err(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", flag_str, val));
    }
    let (num_part, mult) = if val.ends_with('K') || val.ends_with('k') {
        (&val[..val.len()-1], 1024u64)
    } else if val.ends_with('M') || val.ends_with('m') {
        (&val[..val.len()-1], 1024*1024)
    } else if val.ends_with('G') || val.ends_with('g') {
        (&val[..val.len()-1], 1024*1024*1024)
    } else {
        (val, 1)
    };
    if num_part.is_empty() {
        return Err(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", flag_str, val));
    }
    // num_part must be digits only
    if !num_part.chars().all(|c| c.is_ascii_digit()) {
        return Err(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", flag_str, val));
    }
    match num_part.parse::<u64>() {
        Ok(n) => {
            match n.checked_mul(mult) {
                Some(v) => Ok(v),
                None => Err(format!("rg: error parsing flag {}: invalid size: size too large\n", flag_str)),
            }
        }
        Err(_) => Err(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", flag_str, val)),
    }
}

fn unescape_separator(s: &str) -> String {
    // Handle escape sequences like \x7F, \t, \n, etc.? Original says "Escape sequences like \x7F or \t may be used."
    // Need to implement: \t, \n, \r, \\, \xHH, \0? Let's probe original for separators with escapes.
    // For now, implement \t, \n, \r, \\, \xHH, \0?
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('t') => out.push('\t'),
                Some('n') => out.push('\n'),
                Some('r') => out.push('\r'),
                Some('\\') => out.push('\\'),
                Some('0') => out.push('\0'),
                Some('x') => {
                    let h1 = chars.next();
                    let h2 = chars.next();
                    if let (Some(a), Some(b)) = (h1, h2) {
                        if let (Some(v1), Some(v2)) = (a.to_digit(16), b.to_digit(16)) {
                            let v = (v1*16+v2) as u8;
                            out.push(v as char);
                        } else {
                            out.push('\\');
                            out.push('x');
                            out.push(a);
                            out.push(b);
                        }
                    } else {
                        out.push('\\');
                        out.push('x');
                        if let Some(a) = h1 { out.push(a); }
                        if let Some(b) = h2 { out.push(b); }
                    }
                }
                Some(other) => {
                    out.push('\\');
                    out.push(other);
                }
                None => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn parse_args(all_args: &[String], cfg: &mut Config) -> Result<(), (String, i32)> {
    let mut i = 0usize;
    let mut pos_index = 0usize; // for tier positions: use i as pos
    let mut seen_dashdash = false;
    while i < all_args.len() {
        let arg = &all_args[i];
        let cur_pos = i;
        if seen_dashdash {
            cfg.positionals.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            seen_dashdash = true;
            i += 1;
            continue;
        }
        if arg == "-" {
            cfg.positionals.push(arg.clone());
            i += 1;
            continue;
        }
        if arg.starts_with("--") {
            // long flag
            let without = &arg[2..];
            if without.is_empty() {
                // "--" already handled, "---"? Treat as positional? Actually "---" starts with --, without = "-", is that flag "-"? Probably unrecognized.
                // Let's treat as unrecognized flag "---"?
                return Err((format!("rg: unrecognized flag {}\n", arg), 2));
            }
            let (name, eq_val) = if let Some(eq) = without.find('=') {
                (&without[..eq], Some(&without[eq+1..]))
            } else {
                (without, None)
            };
            if is_value_long_flag(name) {
                let flag_str = format!("--{}", name);
                let val: String;
                if let Some(v) = eq_val {
                    val = v.to_string();
                } else {
                    // need next arg
                    if i+1 >= all_args.len() {
                        return Err((format!("rg: missing value for flag {}: missing argument for option '{}'\n", flag_str, flag_str), 2));
                    }
                    i += 1;
                    val = all_args[i].clone();
                }
                // handle value flag
                handle_long_value(cfg, name, &val, &flag_str, cur_pos)?;
                i += 1;
                continue;
            } else if is_bool_long_flag(name) {
                if eq_val.is_some() {
                    let flag_str = format!("--{}", name);
                    let v = eq_val.unwrap();
                    return Err((format!("rg: invalid CLI arguments: unexpected argument for option '{}': \"{}\"\n", flag_str, v), 2));
                }
                handle_long_bool(cfg, name, cur_pos)?;
                i += 1;
                continue;
            } else {
                // unrecognized, strip =value part for message? Already have name without =.
                let flag_show = format!("--{}", name);
                // TODO: suggestions? For now no suggestions.
                return Err((format!("rg: unrecognized flag {}\n", flag_show), 2));
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // short flags, possibly combined
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            let mut consumed_next = false;
            while j < chars.len() {
                let c = chars[j];
                if short_takes_value(c) {
                    let flag_str = format!("-{}", c);
                    // value is rest of arg after c, or next arg
                    let rest: String = chars[j+1..].iter().collect();
                    let val: String;
                    if !rest.is_empty() {
                        // strip leading '=' if present
                        if rest.starts_with('=') {
                            val = rest[1..].to_string();
                        } else {
                            val = rest;
                        }
                    } else {
                        if i+1 >= all_args.len() {
                            return Err((format!("rg: missing value for flag {}: missing argument for option '{}'\n", flag_str, flag_str), 2));
                        }
                        i += 1;
                        val = all_args[i].clone();
                        consumed_next = true;
                    }
                    handle_short_value(cfg, c, &val, &flag_str, cur_pos)?;
                    // value flag consumes rest, break inner loop
                    break;
                } else if is_bool_short(c) {
                    // check for =value? For bool short, if rest starts with '=', it's unexpected argument? e.g., -i=true
                    // Original: "-i=true" gave unexpected argument for '-i': "true"
                    // How to detect? If chars after c start with '=', then rest[1..] is value, error.
                    // But what about "-iv"? That's -i -v, not -i with value "v". For bool, each char is separate, no attached value except with '='?
                    // For "-in", it's -i -n. For "-i=true", rest is "=true", so error.
                    // For "-u"? It's bool but countable, and "-uuu" means three -u, not -u with value "uu".
                    // So for bool, if rest starts with '=', error.
                    let rest: String = chars[j+1..].iter().collect();
                    if rest.starts_with('=') {
                        let flag_str = format!("-{}", c);
                        let v = &rest[1..];
                        return Err((format!("rg: invalid CLI arguments: unexpected argument for option '{}': \"{}\"\n", flag_str, v), 2));
                    }
                    handle_short_bool(cfg, c, cur_pos)?;
                    j += 1;
                    continue;
                } else {
                    return Err((format!("rg: unrecognized flag -{}\n", c), 2));
                }
            }
            i += 1;
            continue;
        } else {
            // positional
            cfg.positionals.push(arg.clone());
            i += 1;
            continue;
        }
    }
    Ok(())
}

fn handle_long_value(cfg: &mut Config, name: &str, val: &str, flag_str: &str, pos: usize) -> Result<(), (String, i32)> {
    match name {
        "regexp" => { cfg.patterns.push(val.to_string()); }
        "file" => { cfg.pattern_files.push(val.to_string()); }
        "pre" => { cfg.pre = Some(val.to_string()); }
        "pre-glob" => {
            // validate glob?
            if let Err(e) = validate_glob(val) {
                return Err((format!("rg: error parsing glob '{}': {}\n", val, e), 2));
            }
            cfg.pre_globs.push(val.to_string());
        }
        "dfa-size-limit" => {
            match parse_size_flag(flag_str, val) {
                Ok(n) => cfg.dfa_size_limit = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        "encoding" => {
            if !is_valid_encoding(val) {
                return Err((format!("rg: error parsing flag {}: grep config error: unknown encoding: {}\n", flag_str, val), 2));
            }
            cfg.encoding = val.to_string();
        }
        "engine" => {
            if val != "default" && val != "pcre2" && val != "auto" {
                return Err((format!("rg: error parsing flag {}: unrecognized regex engine '{}'\n", flag_str, val), 2));
            }
            cfg.engine = val.to_string();
            if val == "pcre2" {
                cfg.pcre2 = true;
            } else if val == "default" {
                cfg.pcre2 = false;
            } else {
                // auto: keep pcre2 false? Actually auto means use pcre2 if needed, but since pcre2 not available, treat as default for now.
                cfg.pcre2 = false;
            }
        }
        "max-count" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.max_count = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        "regex-size-limit" => {
            match parse_size_flag(flag_str, val) {
                Ok(n) => cfg.regex_size_limit = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        "threads" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.threads = n,
                Err(msg) => return Err((msg, 2)),
            }
        }
        "glob" => {
            if let Err(e) = validate_glob(val) {
                return Err((format!("rg: error parsing glob '{}': {}\n", val, e), 2));
            }
            cfg.globs.push(val.to_string());
        }
        "iglob" => {
            if let Err(e) = validate_glob(val) {
                return Err((format!("rg: error parsing glob '{}': {}\n", val, e), 2));
            }
            cfg.iglobs.push(val.to_string());
        }
        "ignore-file" => {
            cfg.ignore_files.push(val.to_string());
        }
        "max-depth" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.max_depth = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        "max-filesize" => {
            match parse_size_flag(flag_str, val) {
                Ok(n) => cfg.max_filesize = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        "type" => {
            cfg.types.push(val.to_string());
        }
        "type-not" => {
            cfg.types_not.push(val.to_string());
        }
        "type-add" => {
            // validate: must contain ':' with non-empty name and glob, and name must be valid? Check original: "foo" (no colon) invalid, "foo:" (empty glob) invalid, ":*.foo" (empty name) invalid.
            if !is_valid_type_add(val) {
                return Err((format!("rg: invalid definition (format is type:glob, e.g., html:*.html)\n"), 2));
            }
            // also need to validate glob part? Original probably validates glob? Let's test --type-add=foo:[ ?
            let parts: Vec<&str> = val.splitn(2, ':').collect();
            let glob_part = parts[1];
            if let Err(e) = validate_glob(glob_part) {
                // What error? Probably same as glob error? Let's test.
                return Err((format!("rg: error parsing glob '{}': {}\n", glob_part, e), 2));
            }
            cfg.type_ops.push((true, val.to_string()));
        }
        "type-clear" => {
            if val.is_empty() {
                return Err((format!("rg: invalid definition (format is type:glob, e.g., html:*.html)\n"), 2));
            }
            cfg.type_ops.push((false, val.to_string()));
        }
        "after-context" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => { cfg.after_context = Some(n); cfg.after_set = true; cfg.after_set_pos = Some(pos); }
                Err(msg) => return Err((msg, 2)),
            }
        }
        "before-context" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => { cfg.before_context = Some(n); cfg.before_set = true; cfg.before_set_pos = Some(pos); }
                Err(msg) => return Err((msg, 2)),
            }
        }
        "color" => {
            if val != "never" && val != "auto" && val != "always" && val != "ansi" {
                return Err((format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", flag_str, val), 2));
            }
            cfg.color = val.to_string();
        }
        "colors" => {
            if let Err(msg) = validate_colors(val) {
                return Err((format!("rg: error parsing flag {}: {}\n", flag_str, msg), 2));
            }
            cfg.colors.push(val.to_string());
        }
        "context" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => { cfg.context_opt = Some(n); cfg.context_set = true; cfg.context_set_pos = Some(pos); }
                Err(msg) => return Err((msg, 2)),
            }
        }
        "context-separator" => {
            cfg.context_separator = Some(unescape_separator(val));
            cfg.context_separator_is_default = false;
        }
        "field-context-separator" => {
            cfg.field_context_separator = unescape_separator(val);
        }
        "field-match-separator" => {
            cfg.field_match_separator = unescape_separator(val);
        }
        "hostname-bin" => {
            cfg.hostname_bin = Some(val.to_string());
        }
        "hyperlink-format" => {
            if let Err(msg) = validate_hyperlink(val) {
                return Err((format!("rg: error parsing flag {}: {}\n", flag_str, msg), 2));
            }
            cfg.hyperlink_format = Some(val.to_string());
        }
        "max-columns" => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.max_columns = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        "path-separator" => {
            if val.is_empty() {
                cfg.path_separator = None;
            } else if val.as_bytes().len() != 1 {
                return Err((format!("rg: error parsing flag {}: A path separator must be exactly one byte, but the given separator is {} bytes: {}\nIn some shells on Windows '/' is automatically expanded. Use '//' instead.\n", flag_str, val.as_bytes().len(), val), 2));
            } else {
                cfg.path_separator = Some(val.as_bytes()[0]);
            }
        }
        "replace" => {
            cfg.replace = Some(val.to_string());
        }
        "sort" => {
            if val != "none" && val != "path" && val != "modified" && val != "accessed" && val != "created" {
                return Err((format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", flag_str, val), 2));
            }
            cfg.sort = Some(val.to_string());
            cfg.sort_pos = Some(pos);
        }
        "sortr" => {
            if val != "none" && val != "path" && val != "modified" && val != "accessed" && val != "created" {
                return Err((format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", flag_str, val), 2));
            }
            cfg.sortr = Some(val.to_string());
            cfg.sortr_pos = Some(pos);
        }
        "generate" => {
            if val != "man" && val != "complete-bash" && val != "complete-zsh" && val != "complete-fish" && val != "complete-powershell" {
                return Err((format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", flag_str, val), 2));
            }
            cfg.generate = Some((val.to_string(), pos));
        }
        _ => unreachable!(),
    }
    Ok(())
}

