fn handle_short_value(cfg: &mut Config, c: char, val: &str, flag_str: &str, pos: usize) -> Result<(), (String, i32)> {
    match c {
        'e' => cfg.patterns.push(val.to_string()),
        'f' => cfg.pattern_files.push(val.to_string()),
        'd' => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.max_depth = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        'g' => {
            if let Err(e) = validate_glob(val) {
                return Err((format!("rg: error parsing glob '{}': {}\n", val, e), 2));
            }
            cfg.globs.push(val.to_string());
        }
        'j' => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.threads = n,
                Err(msg) => return Err((msg, 2)),
            }
        }
        'm' => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.max_count = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        'r' => cfg.replace = Some(val.to_string()),
        't' => cfg.types.push(val.to_string()),
        'A' => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => { cfg.after_context = Some(n); cfg.after_set = true; cfg.after_set_pos = Some(pos); }
                Err(msg) => return Err((msg, 2)),
            }
        }
        'B' => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => { cfg.before_context = Some(n); cfg.before_set = true; cfg.before_set_pos = Some(pos); }
                Err(msg) => return Err((msg, 2)),
            }
        }
        'C' => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => { cfg.context_opt = Some(n); cfg.context_set = true; cfg.context_set_pos = Some(pos); }
                Err(msg) => return Err((msg, 2)),
            }
        }
        'E' => {
            if !is_valid_encoding(val) {
                return Err((format!("rg: error parsing flag {}: grep config error: unknown encoding: {}\n", flag_str, val), 2));
            }
            cfg.encoding = val.to_string();
        }
        'M' => {
            match parse_u64_flag(flag_str, val) {
                Ok(n) => cfg.max_columns = Some(n),
                Err(msg) => return Err((msg, 2)),
            }
        }
        'T' => cfg.types_not.push(val.to_string()),
        _ => unreachable!(),
    }
    Ok(())
}

fn handle_short_bool(cfg: &mut Config, c: char, pos: usize) -> Result<(), (String, i32)> {
    match c {
        'a' => { cfg.text = true; }
        'b' => { cfg.byte_offset = true; }
        'c' => { cfg.count = true; cfg.count_pos = Some(pos); }
        'h' => { cfg.help_short_pos = Some(pos); }
        'i' => { cfg.case_mode = CaseMode::Insensitive; }
        'l' => { cfg.files_with_matches = true; cfg.files_with_matches_pos = Some(pos); }
        'n' => { cfg.line_number = Some(true); }
        'o' => { cfg.only_matching = true; }
        'p' => {
            cfg.color = "always".to_string();
            cfg.heading = Some(true);
            cfg.line_number = Some(true);
        }
        'q' => { cfg.quiet = true; }
        's' => { cfg.case_mode = CaseMode::Sensitive; }
        'u' => {
            if cfg.unrestricted >= 3 {
                return Err((format!("rg: error parsing flag -u: flag can only be repeated up to 3 times\n"), 2));
            }
            cfg.unrestricted += 1;
        }
        'v' => { cfg.invert_match = true; }
        'w' => { cfg.word_regexp = true; }
        'x' => { cfg.line_regexp = true; }
        'z' => { cfg.search_zip = true; }
        'F' => { cfg.fixed_strings = true; }
        'H' => { cfg.with_filename = Some(true); }
        'I' => { cfg.with_filename = Some(false); }
        'L' => { cfg.follow = true; }
        'N' => { cfg.line_number = Some(false); }
        'P' => { cfg.pcre2 = true; }
        'S' => { cfg.case_mode = CaseMode::Smart; }
        'U' => { cfg.multiline = true; }
        'V' => { cfg.version_short_pos = Some(pos); }
        '0' => { cfg.null = true; }
        '.' => { cfg.hidden = true; }
        _ => unreachable!(),
    }
    Ok(())
}
