// Type handling
fn parse_default_types() -> HashMap<String, Vec<String>> {
    let mut map: HashMap<String, Vec<String>> = HashMap::new();
    for line in TYPELIST_TXT.lines() {
        if line.trim().is_empty() { continue; }
        if let Some(idx) = line.find(':') {
            let name = line[..idx].trim().to_string();
            let rest = line[idx+1..].trim();
            let globs: Vec<String> = if rest.is_empty() { Vec::new() } else { rest.split(", ").map(|s| s.to_string()).collect() };
            map.insert(name, globs);
        }
    }
    map
}

fn apply_type_ops(mut map: HashMap<String, Vec<String>>, ops: &[(bool, String)]) -> HashMap<String, Vec<String>> {
    for (is_add, val) in ops {
        if *is_add {
            if let Some(idx) = val.find(':') {
                let name = val[..idx].to_string();
                let glob = val[idx+1..].to_string();
                map.entry(name.clone()).or_insert(Vec::new()).push(glob);
                // sort globs?
                if let Some(v) = map.get_mut(&name) {
                    v.sort();
                }
            }
        } else {
            // clear
            map.remove(val);
        }
    }
    // sort each type's globs? Already sorted for adds, but defaults are already sorted. Ensure sorted.
    for v in map.values_mut() {
        v.sort();
    }
    map
}

