fn collect_patterns_with_data(cfg: &Config, stdin_data: Option<&[u8]>) -> Result<Vec<String>, (String, i32)> {
    let mut pats: Vec<String> = Vec::new();
    for p in &cfg.patterns {
        pats.push(p.clone());
    }
    for pf in &cfg.pattern_files {
        if pf == "-" {
            if let Some(data) = stdin_data {
                let s = String::from_utf8_lossy(data);
                for line in s.lines() {
                    pats.push(line.to_string());
                }
            } else {
                // Should not happen (we already read), but handle
                pats.push(String::new());
            }
        } else {
            match fs::read(pf) {
                Ok(data) => {
                    let s = String::from_utf8_lossy(&data);
                    for line in s.lines() {
                        pats.push(line.to_string());
                    }
                }
                Err(e) => {
                    return Err((format!("rg: {}: {}\n", pf, e), 2));
                }
            }
        }
    }
    if cfg.patterns.is_empty() && cfg.pattern_files.is_empty() {
        if cfg.positionals.is_empty() {
            return Err((format!("rg: ripgrep requires at least one pattern to execute a search\n"), 2));
        } else {
            pats.push(cfg.positionals[0].clone());
        }
    }
    Ok(pats)
}
