fn collect_files(cfg: &Config, paths: &[String], is_default: bool, has_error: &mut bool) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for p in paths {
        if p == "-" {
            continue; // stdin handled separately
        }
        match fs::symlink_metadata(p) {
            Ok(md) => {
                if md.is_file() {
                    out.push(p.clone());
                } else if md.file_type().is_symlink() {
                    match fs::metadata(p) {
                        Ok(t) => {
                            if t.is_file() {
                                out.push(p.clone());
                            } else if t.is_dir() {
                                if cfg.follow {
                                    let mut builder = build_walk(cfg, &[p.clone()]);
                                    if !cfg.no_ignore_files && !cfg.no_ignore && cfg.unrestricted < 1 {
                                        for ig in &cfg.ignore_files {
                                            let _ = builder.add_ignore(ig);
                                        }
                                    }
                                    for entry in builder.build() {
                                        match entry {
                                            Ok(e) => {
                                                if let Some(ft) = e.file_type() {
                                                    if ft.is_file() {
                                                        if !cfg.iglobs.is_empty() && !matches_iglobs(e.path(), &cfg.iglobs) { continue; }
                                                        out.push(path_to_string(e.path(), false, cfg));
                                                    }
                                                }
                                            }
                                            Err(e) => {
                                                if !cfg.no_messages { eprint!("rg: {}\n", e); }
                                                *has_error = true;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        Err(e) => {
                            if !cfg.no_messages { eprint!("rg: {}: {}\n", p, e); }
                            *has_error = true;
                        }
                    }
                } else if md.is_dir() {
                    let mut builder = build_walk(cfg, &[p.clone()]);
                    if !cfg.no_ignore_files && !cfg.no_ignore && cfg.unrestricted < 1 {
                        for ig in &cfg.ignore_files {
                            let _ = builder.add_ignore(ig);
                        }
                    }
                    for entry in builder.build() {
                        match entry {
                            Ok(e) => {
                                if let Some(ft) = e.file_type() {
                                    if ft.is_file() {
                                        if !cfg.iglobs.is_empty() && !matches_iglobs(e.path(), &cfg.iglobs) { continue; }
                                        out.push(path_to_string(e.path(), is_default, cfg));
                                    }
                                }
                            }
                            Err(e) => {
                                if !cfg.no_messages { eprint!("rg: {}\n", e); }
                                *has_error = true;
                            }
                        }
                    }
                }
            }
            Err(e) => {
                // For collect (sorted case with multiple paths?), use short error? For single path sorted? Our collect is called for sorted case which may be single dir or multiple. For single nonexistent with sorting? Unclear. Use same logic as handle_files: if single and NotFound, long, else short.
                let is_single = paths.len() == 1 && !is_default;
                let msg = if is_single && (e.kind() == std::io::ErrorKind::NotFound || e.kind() == std::io::ErrorKind::NotADirectory) {
                    format!("rg: {}: IO error for operation on {}: {}", p, p, e)
                } else {
                    format!("rg: {}: {}", p, e)
                };
                if !cfg.no_messages { eprint!("{}\n", msg); }
                *has_error = true;
            }
        }
    }
    out
}

