fn search_path(cfg: &Config, regex: &regex::bytes::Regex, p: &str, _is_default: bool, with_filename: bool, show_line_numbers: bool, show_heading: bool, colors_enabled: bool, stats: &mut SearchStats, effective_multiline: bool) -> (bool, bool) {
