            if md.is_file() {
                search_single_file(cfg, regex, p, with_filename, show_line_numbers, show_heading, colors_enabled, stats, effective_multiline)
            } else if md.is_dir() {
                search_dir(cfg, regex, p, false, with_filename, show_line_numbers, show_heading, colors_enabled, stats, effective_multiline)
            } else if md.file_type().is_symlink() {
                match fs::metadata(p) {
                    Ok(t) => {
                        if t.is_file() {
                            search_single_file(cfg, regex, p, with_filename, show_line_numbers, show_heading, colors_enabled, stats, effective_multiline)
                        } else if t.is_dir() {
                            if cfg.follow {
                                search_dir(cfg, regex, p, false, with_filename, show_line_numbers, show_heading, colors_enabled, stats, effective_multiline)
                            } else {
                                (false, false)
                            }
                        } else { (false, false) }
                    }
                    Err(e) => {
                        if !cfg.no_messages { eprint!("rg: {}: {}\n", p, e); }
                        (false, true)
                    }
                }
            } else { (false, false) }
        }
        Err(e) => {
            if !cfg.no_messages { eprint!("rg: {}: {}\n", p, e); }
            (false, true)
        }
    }
}

fn search_single_file(cfg: &Config, regex: &regex::bytes::Regex, path: &str, with_filename: bool, show_line_numbers: bool, show_heading: bool, colors_enabled: bool, stats: &mut SearchStats, effective_multiline: bool) -> (bool, bool) {
    search_single_file_sorted(cfg, regex, path, with_filename, show_line_numbers, show_heading, colors_enabled, stats, effective_multiline)
}

fn search_single_file_sorted(cfg: &Config, regex: &regex::bytes::Regex, path: &str, with_filename: bool, show_line_numbers: bool, show_heading: bool, colors_enabled: bool, stats: &mut SearchStats, effective_multiline: bool) -> (bool, bool) {
    // Read file with pre/z/encoding handling
    let (data, read_error) = read_file_data(cfg, path);
    if let Some(err) = read_error {
        if !cfg.no_messages {
            // Format: "rg: <path>: <err>"? For permission denied, short. For other?
            eprint!("rg: {}: {}\n", path, err);
        }
        return (false, true);
    }
    let data = data.unwrap();
    // For explicit files, binary handling: if binary and not --text, print binary message (for normal output) but still count for -l/-c etc.?
    // search_data will handle binary with is_explicit=true
    search_data_explicit(cfg, regex, &data, path, false, Some(path.to_string()), with_filename, show_line_numbers, show_heading, colors_enabled, stats, effective_multiline, true)
}

fn search_dir(cfg: &Config, regex: &regex::bytes::Regex, dir: &str, is_default: bool, with_filename: bool, show_line_numbers: bool, show_heading: bool, colors_enabled: bool, stats: &mut SearchStats, effective_multiline: bool) -> (bool, bool) {
    let mut has_match = false;
    let mut has_error = false;
    let mut builder = build_walk(cfg, &[dir.to_string()]);
    if !cfg.no_ignore_files && !cfg.no_ignore && cfg.unrestricted < 1 {
        for ig in &cfg.ignore_files {
            let _ = builder.add_ignore(ig);
        }
    }
    for entry in builder.build() {
        match entry {
            Ok(e) => {
                if let Some(ft) = e.file_type() {
                    if ft.is_file() {
                        if !cfg.iglobs.is_empty() && !matches_iglobs(e.path(), &cfg.iglobs) { continue; }
                        let disp = path_to_string(e.path(), is_default, cfg);
                        let raw = e.path().to_string_lossy().to_string();
                        // Read and search (non-explicit, so binary skipping applies)
                        let (data, err) = read_file_data(cfg, &raw);
                        if let Some(er) = err {
                            if !cfg.no_messages { eprint!("rg: {}: {}\n", disp, er); }
                            has_error = true;
                            continue;
                        }
                        let data = data.unwrap();
                        let (m, er) = search_data_explicit(cfg, regex, &data, &disp, false, Some(raw), with_filename, show_line_numbers, show_heading, colors_enabled, stats, effective_multiline, false);
                        if m { has_match = true; }
                        if er { has_error = true; }
                        if cfg.quiet && has_match { break; }
                    }
                }
            }
            Err(e) => {
                if !cfg.no_messages { eprint!("rg: {}\n", e); }
                has_error = true;
            }
        }
        if cfg.quiet && has_match { break; }
    }
    (has_match, has_error)
}

