fn transcode_data(cfg: &Config, data: &[u8]) -> Vec<u8> {
    // Handle BOM and encoding
    if cfg.encoding == "none" {
        return data.to_vec();
    }
    // Check BOMs
    if data.len() >= 3 && data[0]==0xEF && data[1]==0xBB && data[2]==0xBF {
        // UTF-8 BOM, strip
        return data[3..].to_vec();
    }
    if data.len() >= 2 && data[0]==0xFF && data[1]==0xFE {
        // UTF-16LE BOM
        let content = &data[2..];
        return decode_utf16le(content);
    }
    if data.len() >= 2 && data[0]==0xFE && data[1]==0xFF {
        // UTF-16BE BOM
        let content = &data[2..];
        return decode_utf16be(content);
    }
    // No BOM: check encoding for utf-16 without BOM
    let enc_lower = cfg.encoding.to_lowercase();
    if enc_lower=="utf-16le" || enc_lower=="ucs-2le" || enc_lower=="utf16le" || enc_lower=="unicodefffe" || enc_lower=="csunicode11" {
        return decode_utf16le(data);
    }
    if enc_lower=="utf-16be" || enc_lower=="utf16be" || enc_lower=="unicodefeff" || enc_lower=="csunicode" {
        return decode_utf16be(data);
    }
    if enc_lower=="utf-16" || enc_lower=="utf16" || enc_lower=="unicode" || enc_lower=="ucs-2" {
        // Default to LE when no BOM? As observed, utf-16 without BOM assumes LE.
        return decode_utf16le(data);
    }
    // For other encodings, assume raw (ASCII compatible)
    data.to_vec()
