        out.insert(typ.to_string(), seq);
    }
    out
}

fn color_to_code(name: &str, is_bg: bool, _codes: &[String]) -> String {
    let lower = name.to_lowercase();
    // Check basic colors
    let base = match lower.as_str() {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" => 5,
        "cyan" => 6,
        "white" => 7,
        _ => {
            // Extended: x or x,x,x
            if name.contains(',') {
                // 24-bit: x,x,x
                let parts: Vec<&str> = name.split(',').collect();
                if parts.len()==3 {
                    let mut vals: Vec<u8> = Vec::new();
                    for p in parts {
                        let p = p.trim();
                        let v = if p.starts_with("0x") || p.starts_with("0X") {
                            u8::from_str_radix(&p[2..], 16).unwrap_or(0)
                        } else {
                            p.parse::<u8>().unwrap_or(0)
                        };
                        vals.push(v);
                    }
                    if is_bg {
                        return format!("48;2;{};{};{}", vals[0], vals[1], vals[2]);
                    } else {
                        return format!("38;2;{};{};{}", vals[0], vals[1], vals[2]);
                    }
                }
            } else {
                // 256-color: x
                let p = name.trim();
                let v = if p.starts_with("0x") || p.starts_with("0X") {
                    u8::from_str_radix(&p[2..], 16).unwrap_or(0)
                } else {
                    p.parse::<u8>().unwrap_or(0)
                };
                if is_bg {
                    return format!("48;5;{}", v);
                } else {
                    return format!("38;5;{}", v);
                }
            }
            // Fallback
            return if is_bg { "49".to_string() } else { "39".to_string() };
        }
    };
    if is_bg {
        format!("{}", 40 + base)
    } else {
        format!("{}", 30 + base)
    }
}
