    let mut out: Vec<u8> = Vec::new();
    let bytes = rep.as_bytes();
    let mut i=0;
    while i < bytes.len() {
        if bytes[i]==b'$' {
            if i+1 < bytes.len() && bytes[i+1]==b'$' {
                out.push(b'$');
                i+=2;
            } else if i+1 < bytes.len() && bytes[i+1]==b'{' {
                // ${...}
