                        out.extend_from_slice(match_text);
                    } else {
                        // empty (since no caps)
                    }
                    i += 2 + end + 1;
                } else {
                    out.push(b'$');
                    i+=1;
                }
            } else if i+1 < bytes.len() && (bytes[i+1].is_ascii_alphanumeric() || bytes[i+1]==b'_') {
