                if name=="0" {
                    out.extend_from_slice(match_text);
                } else {
                    // empty
                }
                i=j;
            } else {
                out.push(b'$');
                i+=1;
            }
        } else {
            out.push(bytes[i]);
            i+=1;
        }
    }
    out
}

