new_sort = """fn sort_file_paths(files: &mut Vec<String>, mode: &(String, bool)) {
    sort_files_list(files, mode);
}

fn sort_tuples(files: &mut Vec<(String,bool)>, mode: &(String, bool)) {
    // Sort by String (path) or by file time (using String for stat), preserving bool
    let (by, rev) = mode;
    match by.as_str() {
        "path" => {
            files.sort_by(|a,b| a.0.cmp(&b.0));
            if *rev { files.reverse(); }
        }
        "modified" | "accessed" | "created" => {
            files.sort_by(|a,b| {
                let ma = std::fs::metadata(&a.0);
                let mb = std::fs::metadata(&b.0);
                let ord = match (ma, mb) {
                    (Ok(aa), Ok(bb)) => {
                        let ta = get_file_time(&aa, by);
                        let tb = get_file_time(&bb, by);
                        ta.cmp(&tb).then_with(|| a.0.cmp(&b.0))
                    }
                    (Ok(_), Err(_)) => std::cmp::Ordering::Less,
                    (Err(_), Ok(_)) => std::cmp::Ordering::Greater,
                    (Err(_), Err(_)) => a.0.cmp(&b.0),
                };
                if *rev { ord.reverse() } else { ord }
            });
        }
        _ => {}
    }
}

