import subprocess, json
def run_orig(args, stdin=None, cwd="/tmp/rgtest"):
    inp=stdin.encode() if isinstance(stdin,str) else stdin
    r=subprocess.run(["/workspace/executable"]+args, input=inp, capture_output=True, cwd=cwd)
    return r.stdout, r.stderr, r.returncode
def run_new(args, stdin=None, cwd="/tmp/rgtest"):
    inp=stdin.encode() if isinstance(stdin,str) else stdin
    r=subprocess.run(["/workspace/target/debug/rg"]+args, input=inp, capture_output=True, cwd=cwd)
    return r.stdout, r.stderr, r.returncode
def cmp_json(args, stdin=None):
    o_out,o_err,o_rc=run_orig(args, stdin)
    n_out,n_err,n_rc=run_new(args, stdin)
    def normalize(data):
        lines=data.decode().strip().split("\n")
        norm=[]
        for line in lines:
            if not line.strip(): continue
            obj=json.loads(line)
            if obj.get("type")=="end":
                if "data" in obj and "stats" in obj["data"] and "elapsed" in obj["data"]["stats"]:
                    obj["data"]["stats"]["elapsed"]={"secs":0,"nanos":0,"human":"X"}
