                    if "stats" in obj["data"] and "elapsed" in obj["data"]["stats"]:
                        obj["data"]["stats"]["elapsed"]={"secs":0,"nanos":0,"human":"X"}
            norm.append(json.dumps(obj, sort_keys=True))
        return sorted(norm)
    o_norm=normalize(o_out)
